contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(uint amount, uint withdrawAmount) public payable {
        require(amount > 0, "amount must be positive");
        require(address(this).balance >= amount, "not enough balance to send");

        uint countBefore = c.depositsCount();
        uint contractBalanceBefore = address(c).balance;

        // Payable call to the fallback increments depositsCount.
        (bool sent, ) = address(c).call{value: amount}("");
        require(sent, "fallback call failed");

        uint countAfter = c.depositsCount();
        uint contractBalanceAfterDeposit = address(c).balance;

        // Verify the fallback incremented depositsCount and received the Ether.
        assert(countAfter == countBefore + 1 && contractBalanceAfterDeposit == contractBalanceBefore + amount);

        uint ownerBalanceBefore = c.owner().balance;

        // Non-owner attempt to withdraw must revert.
        bool nonOwnerWithdrawReverted;
        try c.withdraw(0) {
            nonOwnerWithdrawReverted = false;
        } catch {
            nonOwnerWithdrawReverted = true;
        }

        // Non-owner attempt to send money must revert.
        bool nonOwnerSendReverted;
        try c.sendMoney(address(this), 0) {
            nonOwnerSendReverted = false;
        } catch {
            nonOwnerSendReverted = true;
        }

        assert(nonOwnerWithdrawReverted && nonOwnerSendReverted);

        // Owner can withdraw and the contract balance decreases exactly by the withdrawn amount.
        uint contractBalanceBeforeWithdraw = address(c).balance;
        c.withdraw(withdrawAmount);
        uint contractBalanceAfterWithdraw = address(c).balance;
        uint ownerBalanceAfterWithdraw = c.owner().balance;

        assert(contractBalanceBeforeWithdraw == contractBalanceAfterWithdraw + withdrawAmount);
    }

    receive() external payable {}
}

