contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    receive() external payable {}

    function run(uint amount, uint withdrawAmount, address target, uint sendAmount) public payable {
        require(amount > 0);
        require(address(this).balance >= amount);
        require(withdrawAmount > 0);
        require(sendAmount > 0);

        // Non-owner deposits Ether into c via the fallback.
        uint depositsBefore = c.depositsCount();
        uint contractBalanceBefore = address(c).balance;

        c.call{value: amount}("");

        uint depositsAfter = c.depositsCount();
        uint contractBalanceAfterDeposit = address(c).balance;

        // Owner-only sendMoney must not change depositsCount, even if it succeeds.
        c.sendMoney(target, sendAmount);

        uint depositsAfterSendMoney = c.depositsCount();
        uint contractBalanceAfterSendMoney = address(c).balance;

        // Owner-only withdrawAll must not change depositsCount, even if it succeeds.
        c.withdrawAll();

        uint depositsAfterWithdrawAll = c.depositsCount();

        assert(
            depositsAfter == depositsBefore + 1 &&
            depositsAfterSendMoney == depositsAfter &&
            depositsAfterWithdrawAll == depositsAfterSendMoney &&
            contractBalanceAfterDeposit == contractBalanceBefore + amount &&
            contractBalanceAfterSendMoney == contractBalanceAfterDeposit - sendAmount &&
            address(c).balance == 0
        );
    }
}

