        try c.withdrawAll() { withdrawAllReverted = false; } catch { withdrawAllReverted = true; }
        uint balAfterWithdrawAll = address(c).balance;
        uint depositsAfterWithdrawAll = c.depositsCount();

        bool sendMoneyReverted;
        try c.sendMoney(target, value) { sendMoneyReverted = false; } catch { sendMoneyReverted = true; }
        uint balAfterSendMoney = address(c).balance;
        uint depositsAfterSendMoney = c.depositsCount();

        assert(
            withdrawReverted &&
            withdrawAllReverted &&
            sendMoneyReverted &&
            balAfterWithdraw == balBefore &&
            depositsAfterWithdraw == depositsBefore &&
            balAfterWithdrawAll == balBefore &&
            depositsAfterWithdrawAll == depositsBefore &&
            balAfterSendMoney == balBefore &&
            depositsAfterSendMoney == depositsBefore
        );
    }

    receive() external payable {}
}
